"use strict";
/* Cube Bot のキャラ表示用フレーム。Cube 本体（jisaku-ai-chat）の
   cube_character_frames.js から base（通常）と blink（瞬き）だけを
   抜粋したもの。原本は ~/workspace/cube_character/ の WebP
   （C案：深緑髪・キューブの髪飾り）を 640x640 に縮小し base64 で
   埋め込んである（GitHub push がテキスト専用のため）。
   差し替える時はこの2つの data URI を置き換える。 */
(function (global) {
  const CubeBotCharFrames = {
    base: "data:image/webp;base64,",
    blink: "data:image/webp;base64,",
  };
  global.CubeBotCharFrames = CubeBotCharFrames;
})(typeof window !== "undefined" ? window : globalThis);
